function lzDecompressFromBase64(input) {
  if (input == null || input === "") return "";
  var keyStr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
  var baseRev = {};
  for (var i = 0; i < keyStr.length; i++) {
    baseRev[keyStr.charAt(i)] = i;
  }
  var length = input.length;
  var dictionary = [0, 1, 2];
  var enlargeIn = 4;
  var dictSize = 4;
  var numBits = 3;
  var result = [];
  var dataVal = baseRev[input.charAt(0)];
  var dataPos = 32;
  var dataIdx = 1;
  function readBits(maxpower) {
    var bits = 0;
    var power = 1;
    while (power != maxpower) {
      var resb = dataVal & dataPos;
      dataPos >>= 1;
      if (dataPos == 0) {
        dataPos = 32;
        dataVal = baseRev[input.charAt(dataIdx++)];
      }
      bits |= (resb > 0 ? 1 : 0) * power;
      power <<= 1;
    }
    return bits;
  }
  var c;
  var next = readBits(4);
  if (next == 0) {
    c = String.fromCharCode(readBits(256));
  } else if (next == 1) {
    c = String.fromCharCode(readBits(65536));
  } else if (next == 2) {
    return "";
  }
  dictionary[3] = c;
  var w = c;
  result.push(c);
  while (true) {
    if (dataIdx > length) return "";
    var cc = readBits(1 << numBits);
    if (cc == 0) {
      dictionary[dictSize++] = String.fromCharCode(readBits(256));
      cc = dictSize - 1;
      enlargeIn--;
    } else if (cc == 1) {
      dictionary[dictSize++] = String.fromCharCode(readBits(65536));
      cc = dictSize - 1;
      enlargeIn--;
    } else if (cc == 2) {
      return result.join("");
    }
    if (enlargeIn == 0) {
      enlargeIn = 1 << numBits;
      numBits++;
    }
    var entry;
    if (dictionary[cc]) {
      entry = dictionary[cc];
    } else if (cc === dictSize) {
      entry = w + w.charAt(0);
    } else {
      return "";
    }
    result.push(entry);
    dictionary[dictSize++] = w + entry.charAt(0);
    enlargeIn--;
    w = entry;
    if (enlargeIn == 0) {
      enlargeIn = 1 << numBits;
      numBits++;
    }
  }
}
function unpackMhg(html) {
  var m = html.match(/\}\('(.*?)',(\d+),(\d+),'(.*?)'(?:\['\\x73\\x70\\x6c\\x69\\x63'\]|\.splic)\(/);
  if (!m) return "";
  var p = m[1];
  var a = parseInt(m[2], 10);
  var c = parseInt(m[3], 10);
  var k = lzDecompressFromBase64(m[4]).split("|");
  function encode(n) {
    return (n < a ? "" : encode(parseInt(n / a, 10))) + ((n = n % a) > 35 ? String.fromCharCode(n + 29) : n.toString(36));
  }
  var d = {};
  while (c--) {
    var key = encode(c);
    d[key] = k[c] || key;
  }
  return p.replace(/\b\w+\b/g, function(word) {
    return d[word] !== undefined ? d[word] : word;
  });
}

